(()=>{
 'use strict';
 const $=id=>document.getElementById(id),API='https://rotacerta-mobile.carlosjralfa.chatgpt.site/api/spx',KEY='rota-spx-test-v1';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let state={stops:[],session:null,activeId:null,paused:false,fileName:'',service:3};
 try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&Array.isArray(saved.stops))state={...state,...saved,activeId:null,paused:false};}catch{}
 let selected=state.stops.find(s=>!s.done)?.id||null,position=null,lastPoint=null,watch=null,map=null,markers=[],gpsMarker=null,line=null,eta=null,syncing=false,dirty=false,lastAt=Date.now(),lastSync=0,routeSerial=0,lastRoad=0,responses={},editing=null,storageFailed=false;
 const selectedStop=()=>state.stops.find(s=>s.id===selected),activeStop=()=>state.stops.find(s=>s.id===state.activeId);
 const say=(s,error=false)=>{$('status').textContent=s;$('status').classList.toggle('error',error);};
 const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageFailed){storageFailed=true;say('Armazenamento indisponível. Exporte um backup antes de fechar.',true);}}};
 const fmtTime=ms=>{const n=Math.floor(ms/1000);return `${Math.floor(n/3600).toString().padStart(2,'0')}:${Math.floor(n%3600/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`;};
 const dist=(a,b)=>{const r=Math.PI/180,h=Math.sin((b.lat-a.lat)*r/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin((b.lon-a.lon)*r/2)**2;return 6371000*2*Math.asin(Math.sqrt(Math.min(1,h)));};
 function ensureMap(){if(map||!$('consent').checked)return;if(!window.L){$('map').textContent='Mapa não carregou. Confira a internet e recarregue.';return;}map=L.map('map').setView([-1.4558,-48.4902],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);}
 function renderMap(fit=false){ensureMap();if(!map)return;markers.forEach(m=>m.remove());markers=[];state.stops.forEach((s,i)=>{const m=L.marker([s.lat,s.lon],{icon:L.divIcon({className:'pin'+(s.done?' done':'')+(s.id===selected?' selected':''),html:s.done?'✓':String(i+1),iconSize:[32,32],iconAnchor:[16,16]})}).bindPopup(`<b>${i+1}. ${esc(s.orderRef)}</b><br>${esc(s.street)}`).on('click',()=>{selected=s.id;render();}).addTo(map);markers.push(m);});if(fit&&markers.length)map.fitBounds(L.featureGroup(markers).getBounds().pad(.12));}
 function render(){
  const s=selectedStop();$('fileInfo').textContent=state.fileName?`${state.fileName} · ${state.stops.length} pedidos`:'Arquivo Excel baixado no SPX';$('count').textContent=`Pedidos · ${state.stops.filter(x=>x.done).length}/${state.stops.length}`;
  $('selected').innerHTML=s?`<span class="badge">PARADA ${state.stops.indexOf(s)+1} · ${s.done?'CONCLUÍDA':s.id===state.activeId?'EM ATENDIMENTO':'PENDENTE'}</span><h3 style="margin-top:12px">${esc(s.street)}</h3><p class="muted">${esc(s.orderRef)} · ${esc(s.block)}, ${esc(s.municipality)}</p><button id="editSelected">Editar / cadastrar telefone</button>${responses[s.id]?`<div class="response" style="margin-top:12px"><strong>Cliente respondeu</strong><p>Em casa: ${esc(responses[s.id].home)}</p><p>Recebe: ${esc(responses[s.id].receiver)} ${esc(responses[s.id].name)}</p><p>Contato: ${esc(responses[s.id].phone||'Não informado')}</p><p>Palavra-chave: ${esc(responses[s.id].keyword)}</p><p>${esc(responses[s.id].notes)}</p></div>`:''}`:'<p>Importe o romaneio para ver as paradas no mapa.</p>';
  $('navigate').disabled=!s||s.done;$('complete').disabled=!s||s.done;$('pause').disabled=!state.activeId;$('pause').textContent=state.paused?'Retomar':'Parada';
  $('maps').href=s?`https://www.google.com/maps/dir/?api=1&destination=${s.lat},${s.lon}&travelmode=driving`:'#';$('waze').href=s?`https://waze.com/ul?ll=${s.lat},${s.lon}&navigate=yes`:'#';
  const query=$('search').value.toLocaleLowerCase(),filter=$('filter').value;
  $('list').innerHTML=state.stops.map((x,i)=>({x,i})).filter(({x})=>(filter==='all'||x.done===(filter==='done'))&&[x.orderRef,x.street].join(' ').toLocaleLowerCase().includes(query)).map(({x,i})=>`<div class="stop"><span class="number">${x.done?'✓':i+1}</span><div><strong>${esc(x.street)}</strong><small>${esc(x.orderRef)}${responses[x.id]?' · Cliente respondeu':''}${x.sequence===null?' · Sem sequência SPX':''}</small><div class="row" style="margin-top:8px"><button data-select="${esc(x.id)}">Ver no mapa</button>${x.done?`<button data-undo="${esc(x.id)}">Desfazer</button>`:''}</div></div></div>`).join('')||'<p class="muted">Nenhum pedido nesta lista.</p>';
  const url=linkFor(s?.id);$('shareArea').innerHTML=url?`<div class="row" style="margin-top:12px"><button id="copyLink">Copiar link do cliente</button><button id="whatsapp">Avisar pelo WhatsApp</button></div><small>Contato: ${s.phone?esc(s.phone):'não cadastrado'}. Confirme o envio no WhatsApp.</small>`:'<p class="muted">Crie os links para habilitar o acompanhamento e as respostas.</p>';
  if($('editSelected'))$('editSelected').onclick=()=>edit(s);
  if($('copyLink'))$('copyLink').onclick=async()=>{try{await navigator.clipboard.writeText(url);say('Link individual copiado.');}catch{prompt('Copie o link do cliente:',url);}};
  if($('whatsapp'))$('whatsapp').onclick=()=>{let phone=s.phone.replace(/\D/g,'');if(phone.length===10||phone.length===11)phone='55'+phone;if(!/^55\d{10,11}$/.test(phone)){edit(s);say('Cadastre o WhatsApp do destinatário com DDD antes de enviar.',true);return;}const going=state.activeId===s.id;const message=going?`Olá! Estou indo entregar sua encomenda ${s.orderRef}. Acompanhe e informe quem vai receber: ${url}`:`Olá! Sua encomenda ${s.orderRef} está na minha rota. Informe quem vai receber e acompanhe por este link: ${url}`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');};
  renderMap();metrics();persist();
 }
 function linkFor(id){const session=state.session;if(!session||session.expiresAt<Date.now())return null;const t=session.links.find(l=>l.id===id);if(!t)return null;const u=new URL('cliente.html',location.href);u.hash=new URLSearchParams({route:session.routeId,token:t.token}).toString();return u.href;}
 async function api(action,extra={}){const session=state.session;const r=await fetch(API+(action==='get'?`?route=${encodeURIComponent(session.routeId)}`:''),{method:action==='get'?'GET':'POST',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.ownerToken}:{})},...(action==='get'?{}:{body:JSON.stringify({action,routeId:session?.routeId,...extra})}),signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok){const e=new Error(data.error||'Falha de comunicação');e.status=r.status;throw e;}return data;}
 async function sync(){if(!state.session)return;if(syncing){dirty=true;return;}syncing=true;try{for(let attempt=0;attempt<3;attempt++){try{await api('update',{activeId:state.activeId,paused:state.paused,doneIds:state.stops.filter(s=>s.done).map(s=>s.id),position,eta});break;}catch(e){if(e.status!==409||attempt===2)throw e;}}lastSync=Date.now();}catch(e){say('Acompanhamento: '+e.message,true);}finally{syncing=false;if(dirty){dirty=false;sync();}}}
 async function poll(){if(!state.session)return;try{const data=await api('get');const next=Object.fromEntries(data.responses.filter(s=>s.response).map(s=>[s.id,s.response]));if(JSON.stringify(next)!==JSON.stringify(responses)){responses=next;render();say('Respostas dos clientes atualizadas.');}}catch(e){if(e.status===410){state.session=null;persist();render();say(e.message,true);}}}
 function metrics(){const sums=state.stops.reduce((a,s)=>({km:a.km+(s.km||0),active:a.active+(s.activeMs||0),pause:a.pause+(s.pauseMs||0)}),{km:0,active:0,pause:0});$('km').textContent=sums.km.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});$('elapsed').textContent=fmtTime(sums.active);$('paused').textContent=fmtTime(sums.pause);}
 function tick(){const now=Date.now(),delta=now-lastAt;lastAt=now;const s=activeStop();if(s){if(state.paused)s.pauseMs=(s.pauseMs||0)+delta;else s.activeMs=(s.activeMs||0)+delta;}metrics();}
 function startGPS(){if(watch!==null)return;if(!navigator.geolocation){say('GPS indisponível neste navegador.',true);return;}watch=navigator.geolocation.watchPosition(p=>{const now=Date.now(),q={lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy,observedAt:p.timestamp};position=q;if(map){if(gpsMarker)gpsMarker.setLatLng([q.lat,q.lon]);else gpsMarker=L.circleMarker([q.lat,q.lon],{radius:8,color:'#fff',weight:2,fillColor:'#1875d1',fillOpacity:1}).addTo(map).bindTooltip('Sua posição');}const s=activeStop();if(s&&!state.paused&&lastPoint&&q.accuracy<=50&&lastPoint.accuracy<=50){const dt=(q.observedAt-lastPoint.observedAt)/1000,d=dist(lastPoint,q);if(dt>0&&dt<30&&d/dt<45&&d>Math.max(5,(q.accuracy+lastPoint.accuracy)/4))s.km=(s.km||0)+d/1000;}lastPoint=q;$('gps').textContent=`GPS ±${Math.round(q.accuracy)} m`;if(s&&!state.paused&&now-lastRoad>60000){lastRoad=now;road(s);}if(now-lastSync>12000)sync();persist();metrics();},e=>{if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;$('gps').textContent='Ativar GPS';say(e.code===1?'Permita a localização nas configurações do navegador.':'Não foi possível obter o GPS. Tente novamente.',true);},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
 async function road(s){const serial=++routeSerial;eta=null;if(position)lastRoad=Date.now();if(!position||!$('consent').checked){$('roadInfo').textContent='Ative o GPS e autorize o mapa para calcular o caminho.';return;}try{const r=await fetch(`https://router.project-osrm.org/route/v1/driving/${position.lon},${position.lat};${s.lon},${s.lat}?overview=full&geometries=geojson`,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const d=await r.json(),route=d.routes?.[0];if(!route||d.code!=='Ok')throw Error();if(serial!==routeSerial||state.activeId!==s.id)return;eta=Date.now()+(route.duration+state.service*60)*1000;if(line)line.remove();if(map){line=L.geoJSON(route.geometry,{style:{color:'#0e7a70',weight:5}}).addTo(map);map.fitBounds(line.getBounds().pad(.12));}$('roadInfo').textContent=`Até esta parada: ${(route.distance/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})} km · cerca de ${Math.ceil(route.duration/60+state.service)} min, incluindo atendimento. Sem trânsito ao vivo.`;sync();}catch{$('roadInfo').textContent='Cálculo viário indisponível agora. Use Maps ou Waze. Nenhuma distância foi inventada.';}}
 async function navigate(){const s=selectedStop();if(!s||s.done)return;if(!$('consent').checked){say('Autorize o mapa primeiro.',true);return;}tick();state.activeId=s.id;state.paused=false;lastPoint=null;lastRoad=0;ensureMap();startGPS();say('Navegação iniciada. Use “Avisar pelo WhatsApp” para confirmar o envio ao cliente.');render();sync();await road(s);}
 async function createLinks(){if(!state.stops.length)return say('Importe o Excel primeiro.',true);if(state.session&&state.session.expiresAt>Date.now())return say('Links já criados. Selecione um pedido e copie seu link.');if(!confirm('Criar links por 24 horas? Códigos BR, endereços e coordenadas serão enviados ao servidor para o acompanhamento.'))return;$('tracking').disabled=true;try{state.session=await api('start',{stops:state.stops});persist();render();await sync();say('Links individuais prontos. Selecione o pedido e toque em Copiar link do cliente.');}catch(e){say(e.message,true);}finally{$('tracking').disabled=false;}}
 async function end(){if(!state.session)return;if(!confirm('Encerrar todos os links desta rota?'))return;await api('finish');state.session=null;state.activeId=null;responses={};persist();render();say('Links encerrados.');}
 function edit(s){editing=s.id;$('street').value=s.street;$('lat').value=s.lat;$('lon').value=s.lon;$('phone').value=s.phone||'';$('editDialog').showModal();}
 $('editForm').onsubmit=e=>{if(e.submitter?.value!=='save')return;e.preventDefault();const s=state.stops.find(s=>s.id===editing),lat=Number($('lat').value),lon=Number($('lon').value),street=$('street').value.trim();if(!street||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return say('Confira endereço e coordenadas.',true);if(state.session&&(street!==s.street||lat!==s.lat||lon!==s.lon))return say('Encerre o acompanhamento antes de alterar endereço ou ponto. O telefone pode ser alterado.',true);Object.assign(s,{street,lat,lon,phone:$('phone').value.trim()});$('editDialog').close();eta=null;render();};
 $('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(!/\.xlsx$/i.test(file.name))throw Error('Selecione um arquivo .xlsx.');if(state.session)throw Error('Encerre o acompanhamento antes de importar outra rota.');const parsed=await SPXReader.read(await file.arrayBuffer(),window.JSZip,window);if(state.stops.length&&!confirm('Substituir os pedidos atuais pelos pedidos deste arquivo?'))return;tick();state.stops=parsed.stops;state.fileName=file.name;state.activeId=null;state.paused=false;selected=state.stops[0].id;responses={};position=null;lastPoint=null;eta=null;if(line){line.remove();line=null;}render();renderMap(true);say(`${state.stops.length} pedidos importados; ${parsed.unsequenced} sem sequência incluídos; ${parsed.duplicates} duplicados removidos.`);}catch(e){say('Importação: '+e.message,true);}finally{$('file').value='';}};
 $('gps').onclick=()=>{if(!$('consent').checked)return say('Autorize o mapa antes de ativar o GPS.',true);ensureMap();startGPS();};$('consent').onchange=()=>{if($('consent').checked){renderMap(true);}else{if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;position=null;lastPoint=null;if(map){map.remove();map=null;gpsMarker=null;line=null;markers=[];}sync();}};
 $('navigate').onclick=navigate;$('pause').onclick=()=>{tick();state.paused=!state.paused;lastPoint=null;eta=null;render();sync();if(!state.paused&&activeStop())road(activeStop());};
 $('complete').onclick=()=>{const s=selectedStop();if(!s||s.done)return;if(!confirm('Marcar este pedido como concluído no gerenciador? A baixa oficial deve ser feita no SPX.'))return;tick();s.done=true;if(state.activeId===s.id){state.activeId=null;state.paused=false;eta=null;routeSerial++;if(line){line.remove();line=null;}$('roadInfo').textContent='Selecione a próxima parada e toque em Navegar.';}selected=state.stops.find(s=>!s.done)?.id||s.id;render();sync();};
 $('original').onclick=()=>{state.stops.sort((a,b)=>(a.sequence??Infinity)-(b.sequence??Infinity));render();say('Ordem SPX restaurada; pedidos sem sequência ficam no final.');};
 $('optimize').onclick=()=>{if(!position)return say('Ative o GPS para ordenar a partir de sua posição.',true);if(state.activeId)return say('Conclua o atendimento atual antes de reordenar.',true);const remaining=state.stops.filter(s=>!s.done),ordered=[];let p=position;while(remaining.length){let best=0;for(let i=1;i<remaining.length;i++)if(dist(p,remaining[i])<dist(p,remaining[best]))best=i;const s=remaining.splice(best,1)[0];ordered.push(s);p=s;}state.stops=[...state.stops.filter(s=>s.done),...ordered];selected=ordered[0]?.id;render();say('Sequência sugerida por proximidade geográfica. Não considera sentidos das vias; confira o trajeto no mapa.');};
 $('tracking').onclick=createLinks;$('center').onclick=()=>{renderMap(true);if(map&&position)map.setView([position.lat,position.lon],16);};$('filter').onchange=render;$('search').oninput=render;
 $('list').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select){selected=b.dataset.select;render();const s=selectedStop();if(map)map.setView([s.lat,s.lon],17);$('map').scrollIntoView({behavior:'smooth',block:'center'});}if(b.dataset.undo){state.stops.find(s=>s.id===b.dataset.undo).done=false;render();sync();}};
 $('service').value=state.service;$('service').onchange=()=>{const n=Number($('service').value);if(n>=0&&n<=30){state.service=n;persist();}else $('service').value=state.service;};
 $('backup').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='SPX-backup-privado.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('endTracking').onclick=()=>end().catch(e=>say(e.message,true));$('clear').onclick=()=>{if(state.session)return say('Encerre os links primeiro.',true);if(confirm('Apagar todos os pedidos e contatos deste navegador?')){if(watch!==null)navigator.geolocation.clearWatch(watch);localStorage.removeItem(KEY);location.reload();}};
 for(const id of ['maps','waze'])$(id).onclick=e=>{if(!selectedStop()){e.preventDefault();return;}if(state.activeId!==selected){e.preventDefault();say('Toque em Navegar primeiro para iniciar tempo e acompanhamento.',true);}};
 document.addEventListener('visibilitychange',()=>{tick();persist();if(!document.hidden){lastPoint=null;poll();sync();}});
 render();setInterval(()=>{tick();persist();if(state.session&&Date.now()-lastSync>15000)sync();},5000);setInterval(poll,15000);if(state.session){sync();poll();}
})();
